<?php
// Runs inside the disposable authenticated Audience integration suite.
$tfChecks=$checks;$tfPath='audience.php?view=templates&tab=saved';$tfArchive='audience.php?view=templates&tab=archived';
$tfVersion=static fn()=>$campaignStore->contentSettings()['version'];
$tfFolders=static fn()=>$campaignStore->emailTemplateFolders($campaignStore->contentSettings()['settings']);
$tfRequest=static fn(string $operation,string $name,string $newName='')=>['csrf_token'=>$token,'action'=>'template_folder','operation'=>$operation,'name'=>$name,'new_name'=>$newName,'version'=>$tfVersion()];
$tfSettings=$campaignStore->contentSettings()['settings'];
$tfCreate=$tfRequest('create','Folder lifecycle');
audienceHttpExpect(!str_contains($reviewer($tfPath)['body'],'data-open-dialog="template-folder"'),'Reviewers have no folder manager');
audienceHttpExpect($reviewer($tfPath,array_replace($tfCreate,['csrf_token'=>$reviewToken]))['status']===403,'Reviewer folder creation denied');
audienceHttpExpect($editor($tfPath,array_replace($tfCreate,['csrf_token'=>'invalid']))['status']===400,'Template folders require valid CSRF');
$tfResponse=$editor($tfPath,$tfCreate);
audienceHttpExpect($tfResponse['status']===302&&str_contains($tfResponse['headers'],'tab=saved')&&in_array('Folder lifecycle',$tfFolders(),true),'Editors create persistent empty template folders');
foreach([$tfPath,$tfArchive]as$tfScreen){$tfHtml=$editor($tfScreen)['body'];audienceHttpExpect(str_contains($tfHtml,'<option>Folder lifecycle</option>')&&str_contains($tfHtml,'<option value="unfiled">Unfiled</option>')&&str_contains($tfHtml,'Only empty folders can be deleted. Archived templates also count.')&&!preg_match('/(?:Warning|Deprecated|Fatal error):/',$tfHtml),'Empty folders and Unfiled available in saved and archived views');}
audienceHttpExpect($editor($tfPath,$tfCreate)['status']===200&&count(array_keys($tfFolders(),'Folder lifecycle',true))===1,'Stale folder submission cannot duplicate a folder');
audienceHttpExpect($editor($tfPath,array_replace($tfRequest('create','Invalid'),['name'=>['invalid']]))['status']===200,'Malformed folder names render validation without a server error');
$tfDuplicate=$editor($tfPath,$tfRequest('create','Folder lifecycle'));
audienceHttpExpect(str_contains($tfDuplicate['body'],'Choose a unique folder name')&&str_contains($tfDuplicate['body'],'data-reopen-dialog'),'Duplicate folder error reopens management for correction');
foreach(['','Unfiled']as$tfInvalid)audienceHttpExpect($editor($tfPath,$tfRequest('create',$tfInvalid))['status']===200&&!in_array($tfInvalid,$tfFolders(),true),'Empty and reserved folder names rejected');
$tfAdminCreate=$tfRequest('create','Admin empty folder');$tfAdminCreate['csrf_token']=audienceHttpCsrf($admin($tfPath));
audienceHttpExpect($admin($tfPath,$tfAdminCreate)['status']===302,'Administrators can create template folders without unlocking');
audienceHttpExpect($editor($tfPath,$tfRequest('delete','Admin empty folder'))['status']===302&&!in_array('Admin empty folder',$tfFolders(),true),'Editor can delete an empty folder');
$tfId=$campaignStore->createEmailTemplate('Folder member',$design);$tfArchived=$campaignStore->createEmailTemplate('Archived folder member',$design,'Folder lifecycle');
$tfUnfiledHtml=$editor($tfPath)['body'];preg_match('~data-template-key="saved:'.$tfId.'".*?<p>(.*?)</p>~s',$tfUnfiledHtml,$tfUnfiledMatch);
audienceHttpExpect(($tfUnfiledMatch[1]??'')==='Unfiled','Templates without a folder are labeled Unfiled');
$campaignStore->emailTemplateOperation('archive',$tfArchived,1,[]);
$tfMove=['csrf_token'=>$token,'action'=>'template_operation','operation'=>'folder','id'=>$tfId,'version'=>1,'folder'=>'Folder lifecycle'];
audienceHttpExpect($editor($tfPath,array_replace($tfMove,['folder'=>'Missing folder']))['status']===200&&$campaignStore->emailTemplate($tfId)['folder']==='','Unknown move destination rejected without changing membership');
audienceHttpExpect($editor($tfPath,$tfMove)['status']===302&&$campaignStore->emailTemplate($tfId)['folder']==='Folder lifecycle','Template moves into a managed folder');
$tfNonempty=$editor($tfPath,$tfRequest('delete','Folder lifecycle'));
audienceHttpExpect(str_contains($tfNonempty['body'],'This folder contains templates')&&in_array('Folder lifecycle',$tfFolders(),true),'Folder containing saved templates cannot be deleted');
$tfSnapshot=$campaignStore->emailTemplate($tfId)['design'];
audienceHttpExpect($editor($tfPath,$tfRequest('rename','Folder lifecycle','Renamed folder'))['status']===302,'Editor renames a template folder');
$tfActive=$campaignStore->emailTemplate($tfId);$tfOld=$campaignStore->emailTemplate($tfArchived,false,true);
audienceHttpExpect($tfActive['folder']==='Renamed folder'&&$tfOld['folder']==='Renamed folder'&&(int)$tfActive['version']===3&&(int)$tfOld['version']===3&&$tfActive['design']===$tfSnapshot,'Folder rename updates saved and archived membership with version protection and preserves design');
audienceHttpExpect(!in_array('Folder lifecycle',$tfFolders(),true)&&in_array('Renamed folder',$tfFolders(),true),'Renamed folder replaces the original choice');
audienceHttpExpect($editor($tfPath,array_replace($tfMove,['folder'=>'Renamed folder','version'=>2]))['status']===200&&$campaignStore->emailTemplate($tfId)['version']==3,'Folder rename invalidates stale template forms');
audienceHttpExpect($editor($tfPath,array_replace($tfMove,['folder'=>'','version'=>3]))['status']===302,'Unfile moves a saved template out of its folder');
$tfArchivedOnly=$editor($tfArchive,$tfRequest('delete','Renamed folder'));
audienceHttpExpect(str_contains($tfArchivedOnly['body'],'including any archived templates')&&$campaignStore->emailTemplate($tfArchived,false,true)['folder']==='Renamed folder','Archived-only folders cannot be deleted');
$campaignStore->emailTemplateOperation('restore',$tfArchived,3,[]);$campaignStore->emailTemplateOperation('folder',$tfArchived,4,['folder'=>'']);
$tfDelete=$editor($tfArchive,$tfRequest('delete','Renamed folder'));
audienceHttpExpect($tfDelete['status']===302&&str_contains($tfDelete['headers'],'tab=archived')&&!in_array('Renamed folder',$tfFolders(),true),'Empty-folder deletion persists and keeps archived view');
audienceHttpExpect($editor($tfPath,array_replace($tfMove,['folder'=>'Renamed folder','version'=>4]))['status']===200&&$campaignStore->emailTemplate($tfId)['folder']==='','A removed destination cannot be resurrected by a stale move form');
// Existing free-text Save as template behavior registers its folder as well.
$tfSaved=$editor('audience.php?view=designer&kind=template&id='.$copy,['csrf_token'=>$token,'action'=>'design_template','version'=>$campaignStore->emailTemplate($copy)['version'],'name'=>'Folder save-as member','folder'=>'From designer']);
$tfSavedId=(int)(json_decode($tfSaved['body'],true)['id']??0);
audienceHttpExpect($tfSaved['status']===200&&$tfSavedId>0&&in_array('From designer',$tfFolders(),true),'Designer Save as template registers a new folder');
$campaignStore->emailTemplateOperation('folder',$tfSavedId,1,['folder'=>'']);
audienceHttpExpect(in_array('From designer',$tfFolders(),true),'Saved folder remains when its last member is unfiled');
$campaignStore->emailTemplateFolder('delete','From designer','',$tfVersion());
// Older template folders are adopted even if there is no settings entry yet.
$tfLegacy=$campaignStore->createEmailTemplate('Legacy folder member',$design);$campaignStore->write('UPDATE marketing_email_templates SET folder=? WHERE id=?',['Legacy folder',$tfLegacy]);
audienceHttpExpect(in_array('Legacy folder',$tfFolders(),true),'Legacy template folders remain available');
$campaignStore->emailTemplateOperation('folder',$tfLegacy,1,['folder'=>'']);
audienceHttpExpect(in_array('Legacy folder',$tfFolders(),true),'Moving the last legacy member preserves its empty folder');
$campaignStore->emailTemplateFolder('delete','Legacy folder','',$tfVersion());
$tfLegacyDelete=$campaignStore->createEmailTemplate('Legacy archived member',$design);$campaignStore->write('UPDATE marketing_email_templates SET folder=? WHERE id=?',['Legacy archived folder',$tfLegacyDelete]);
$campaignStore->emailTemplateOperation('archive',$tfLegacyDelete,1,[]);$campaignStore->emailTemplateOperation('delete',$tfLegacyDelete,2,[]);
audienceHttpExpect(in_array('Legacy archived folder',$tfFolders(),true),'Permanently deleting the last legacy template preserves its empty folder');
$campaignStore->emailTemplateFolder('delete','Legacy archived folder','',$tfVersion());
$campaignStore->emailTemplateFolder('create','Case folder','',$tfVersion());$campaignStore->emailTemplateFolder('create','case folder','',$tfVersion());
$tfUpper=$campaignStore->createEmailTemplate('Uppercase folder member',$design,'Case folder');$tfLower=$campaignStore->createEmailTemplate('Lowercase folder member',$design,'case folder');
$campaignStore->emailTemplateFolder('rename','Case folder','Case renamed',$tfVersion());
audienceHttpExpect($campaignStore->emailTemplate($tfUpper)['folder']==='Case renamed'&&$campaignStore->emailTemplate($tfLower)['folder']==='case folder','Folder rename matches the exact folder name, independent of database collation');
$campaignStore->emailTemplateOperation('folder',$tfUpper,2,['folder'=>'']);$campaignStore->emailTemplateFolder('delete','Case renamed','',$tfVersion());
$campaignStore->emailTemplateFolder('create','Case folder','',$tfVersion());$campaignStore->emailTemplateFolder('delete','Case folder','',$tfVersion());
audienceHttpExpect($campaignStore->emailTemplate($tfLower)['folder']==='case folder','Deleting an empty folder preserves a differently capitalized populated folder');
$tfMarkup='<b>Folder & name</b>';$campaignStore->emailTemplateFolder('create',$tfMarkup,'',$tfVersion());$tfMarkupPage=$editor($tfPath)['body'];
audienceHttpExpect(str_contains($tfMarkupPage,'&lt;b&gt;Folder &amp; name&lt;/b&gt;')&&!str_contains($tfMarkupPage,'<option>'.$tfMarkup.'</option>'),'Folder labels are escaped in filters and management controls');
$campaignStore->emailTemplateFolder('delete',$tfMarkup,'',$tfVersion());
$tfForeign=$otherStore->createEmailTemplate('Foreign folder member',$design,'Scoped folder');
audienceHttpExpect(!in_array('Scoped folder',$tfFolders(),true),'Foreign folders are not visible');
$campaignStore->emailTemplateFolder('create','Scoped folder','',$tfVersion());
$campaignStore->emailTemplateFolder('delete','Scoped folder','',$tfVersion());
audienceHttpExpect($otherStore->emailTemplate($tfForeign)['folder']==='Scoped folder','Folder emptiness and deletion are audience-scoped');
audienceHttpExpect(($campaignStore->contentSettings()['settings']['content_folders']??[])===($tfSettings['content_folders']??[])&&($campaignStore->contentSettings()['settings']['brand']??[])===($tfSettings['brand']??[]),'Template folder changes preserve My Files folders and Brand Kit settings');
echo 'Audience template folder HTTP checks passed: '.($checks-$tfChecks)."\n";
